query:
SELECT customer_id, name, city
FROM Customers
ORDER BY customer_id;

WITH Ranked AS (
  SELECT order_id, customer_id, ordered_on,
    ROW_NUMBER() OVER (
      PARTITION BY customer_id ORDER BY ordered_on DESC, order_id DESC
    ) AS rn
  FROM Orders
)
SELECT customer_id, order_id, ordered_on
FROM Ranked WHERE rn = 1
ORDER BY customer_id;

SELECT order_id, status
FROM Orders WHERE order_id IN (101, 102)
ORDER BY order_id;
